import json
import logging
import time
from typing import Union

import requests
from requests.auth import HTTPBasicAuth
from taf.internal.impact_radar import log_radar

from .exceptions import SsdOperationError

requests.packages.urllib3.disable_warnings()  # type: ignore[attr-defined]
logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SsdRestApi:

    def __init__(self, web_url: str, username: str, password: str) -> None:
        self.web_url = web_url
        self.web_username = username
        self.web_password = password
        self.url_execute = f'https://{self.web_url}/sm-operations/api/sm/operations/v1/execute'
        self.url_request = f'https://{self.web_url}/sm-operations/api/sm/operations/v1/request'

    def import_ssd(self, input_file: str, file_format: str = 'RAML2', overwrite: bool = False) -> dict:
        """
        Import SSD detail into NetAct by reading the data from a RAML2.1 or a JSON file.

        :param str input_file: path to input data file
        :param string file_format: Indicates the ``JSON`` or ``RAML2`` (RAML2.1) file format
        :param bool overwrite: indicates if the operation overwrites the previous contents, defaults to ``False``.
            It must be set to ``True`` to overwrite the previous contents. If ``overwrite`` is set to ``False``
            and SSD is already available in NetAct for given DNs in the input file, then the operation fails
        """
        if file_format.lower() == 'json':
            endpoint = '/ssd-import'
            content_type = 'application/vnd.nokia-sm-import-request-v1+json'
            with open(input_file) as f:
                data = json.dumps(json.loads(f.read()))
        elif file_format.lower() == 'raml2':
            endpoint = '/ssd-plan-import'
            content_type = 'application/vnd.nokia-sm-import-request-v1+xml'
            with open(input_file) as f:
                data = f.read()
        else:
            raise ValueError(f'Unsupported input file format: {file_format}')

        api_endpoint = self.url_execute + endpoint
        headers = {
            'Content-Type': content_type,
        }
        params = {
            'overwrite': str(overwrite).lower()
        }
        auth = HTTPBasicAuth(self.web_username, self.web_password)

        response = self._post(api_endpoint, headers, params, data, auth)
        return self._process_api_response(response)

    def delete_ssd(self, scope: Union[str, list[str]], delete_any_mo: bool = False) -> dict:
        """
        Delete the SSD of those DNs which were previously imported to MantaRay NM.

        .. note::
            - The underlying API does not delete the SSD content in the network element. The delete API is useful to delete
            the invalid SSD imported to MantaRay NM before provisioning to the network element
            - If one or more DN SSD details are not present, then the delete operation is partially successful.
            If all DNs do not have the SSD detail, then the operation fails completely

        :param str|list(str) scope: DN or a list of DNs subject for the operation
        :param bool delete_any_mo: Set to ``True`` to delete any managed object for the given DN which has valid SSD.
             If set to ``False``, the procedure deletes only the managed object for the given DN which is under MRBTS
        """
        endpoint = '/ssd-delete'
        api_endpoint = self.url_execute + endpoint
        headers = {
            'Content-Type': 'application/vnd.nokia-sm-delete-request-v1+json',
        }
        params = {
            'deleteAnyMO': str(delete_any_mo).lower()
        }
        if not isinstance(scope, list):
            scope = [scope]
        data = json.dumps(
            {"operationAttributes": {"scope": scope}}
        )
        auth = HTTPBasicAuth(self.web_username, self.web_password)

        response = self._post(api_endpoint, headers, params, data, auth)
        return self._process_api_response(response)

    def provision_ssd(self, scope, timeout=120):
        """
        Provision the RUs SSD detail to the network element. Before triggering the operation,
        one must import SSD to MantaRay NM for the given Distinguished Name (DN).

        .. note::
            - DNs used for provisioning must be scope authorized. Otherwise, the operation ignores the DNs
            which do not have a scope.
            - The user must have SSD object provisioning permission.

        :param str|list(str) scope: DN or a list of DNs subject for the operation
        :param int timeout: Timeout for executing operation
        :return: Status of operation
        :rtype: dict
        """
        output = self.start_provision_ssd(scope)
        logger.debug(output)
        operation_id = output['operationId']

        start_time = time.monotonic()
        while time.monotonic() - start_time < timeout:
            status = self.get_status_of_provision_ssd(operation_id)
            logger.debug(status)

            if status['status'].lower() == 'completed':
                return status

            time.sleep(10)  # ???
        else:
            msg = f'Provisioning SSD ({operation_id}) timed out'
            raise SsdOperationError(msg)

    def start_provision_ssd(self, scope):
        endpoint = '/start/ne3s-ssd-ne-provision-raml2'
        api_endpoint = self.url_request + endpoint
        headers = {
            'Content-Type': 'application/vnd.nokia-sm-provision-request-v1+json',
        }
        params = {}
        if not isinstance(scope, list):
            scope = [scope]
        data = json.dumps(
            {"operationAttributes": {"scope": scope}}
        )
        auth = HTTPBasicAuth(self.web_username, self.web_password)

        response = self._post(api_endpoint, headers, params, data, auth)
        return self._process_api_response(response)

    def get_status_of_provision_ssd(self, operation_id):
        """
        Fetch the status of the provisioning operation that was triggered previously

        :param str operation_id: id of the operation returned in `provision_ssd` output,
            e.g., SSD.1635828670811

        :return: Status of operation
        :rtype: dict
        """
        endpoint = '/status'
        api_endpoint = self.url_request + endpoint
        headers = {
            'Content-Type': 'application/vnd.nokia-sm-status-request-v1+json',
        }
        params = {}
        data = json.dumps(
            {"operationId": operation_id}
        )
        auth = HTTPBasicAuth(self.web_username, self.web_password)

        response = self._post(api_endpoint, headers, params, data, auth)
        return self._process_api_response(response)

    @staticmethod
    def _post(api_endpoint, headers=None, params=None, data=None, auth=None):
        log_radar(
            "Sending NetAct request",
            request_method="POST",
            request_url=api_endpoint,
            request_params=params,
            request_data=data,
        )
        return requests.post(api_endpoint,
                             headers=headers,
                             params=params,
                             data=data,
                             auth=auth,
                             verify=False)

    @classmethod
    def _process_api_response(cls, response):
        response.raise_for_status()
        response_json = response.json()
        logger.debug(response_json)
        if len(response_json['errors']) > 0:
            raise SsdOperationError(response_json['message'])
        return response_json
